package dev.equo.swt.size;

/** The text style List items are drawn in. Generated by measure_list.dart. */
public final class ListTheme {
    private final TextStyle textStyle;

    public ListTheme(TextStyle textStyle) {
        this.textStyle = textStyle;
    }

    public TextStyle textStyle() { return textStyle; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof ListTheme)) return false;
        ListTheme other = (ListTheme) o;
        return java.util.Objects.equals(textStyle, other.textStyle);
    }

    @Override
    public int hashCode() { return java.util.Objects.hash(textStyle); }

    @Override
    public String toString() { return "ListTheme[textStyle=" + textStyle + "]"; }

    public static ListTheme get() {
        return Themes.getTheme().list;
    }

    public static ListTheme getNonDefaultTheme() {
        return new ListTheme(new TextStyle("Inter", 14, false, 500, 1.1428571428571428));
    }

    public static ListTheme getDefaultTheme() {
        return new ListTheme(new TextStyle("Inter", 14, false, 500, 1.1428571428571428));
    }

    public static ListTheme getCompactTheme() {
        return new ListTheme(new TextStyle("Inter", 10, false, 500, 1.1428571428571428));
    }

}
